  :NEW.UPDATED_AT := SYSDATE;
END;
/
MERGE INTO HDR_SETTINGS t
USING (SELECT 'adms.auto_add' k, 'N' v FROM DUAL                  -- N: a new terminal waits for approval; Y: added on first contact
       UNION ALL SELECT 'adms.lock_ip', 'net' FROM DUAL           -- on approval: ip = its address only, net = its network (a.b.c.), none
       UNION ALL SELECT 'adms.gate_key', '' FROM DUAL             -- secret the web server in front adds as X-Hader-Gate (empty = not used)
       UNION ALL SELECT 'adms.default_area', '' FROM DUAL          -- area code new terminals join
       UNION ALL SELECT 'adms.timezone', '' FROM DUAL             -- hours; empty = the database clock's offset
       UNION ALL SELECT 'adms.upload_photos', 'N' FROM DUAL       -- punch photos
       UNION ALL SELECT 'adms.trust_proxy', 'N' FROM DUAL         -- behind a web server: the terminal's address from X-Forwarded-For
       UNION ALL SELECT 'adms.sync_bio', 'Y' FROM DUAL            -- templates enrolled on one terminal go to the others
       UNION ALL SELECT 'adms.read_bio_on_punch', 'Y' FROM DUAL   -- ask a terminal for a person's data when it is missing
       UNION ALL SELECT 'devices.write', 'N' FROM DUAL            -- changes are sent to the terminals (starts off)
       UNION ALL SELECT 'traffic.keep_days', '3' FROM DUAL
       -- attendance rules (the same as Hader's)
       UNION ALL SELECT 'att.dup_punch_minutes', '1' FROM DUAL     -- punches closer than this count once
       UNION ALL SELECT 'att.no_in', 'incomplete' FROM DUAL        -- no check-in: incomplete / late / absent
       UNION ALL SELECT 'att.no_in_minutes', '60' FROM DUAL
       UNION ALL SELECT 'att.no_out', 'incomplete' FROM DUAL       -- no check-out: incomplete / early / absent
       UNION ALL SELECT 'att.no_out_minutes', '60' FROM DUAL
       UNION ALL SELECT 'att.late_full', 'Y' FROM DUAL             -- beyond the grace: count all minutes late
       UNION ALL SELECT 'att.ot_mode', 'auto' FROM DUAL            -- auto / approval / both
       UNION ALL SELECT 'access.portal_match', 'email' FROM DUAL     -- the employee of an APEX user without an account: account / email / email_number
       UNION ALL SELECT 'access.employee_check', '' FROM DUAL       -- the institution's function (user name) -> Y for its employees; empty = none
       UNION ALL SELECT 'access.email_domain', '' FROM DUAL         -- the institution's e-mail domain: a name matches what comes before @ there only; empty = whole addresses only
       UNION ALL SELECT 'att.ot_min_minutes', '30' FROM DUAL
       UNION ALL SELECT 'att.ot_before_work', 'N' FROM DUAL
       UNION ALL SELECT 'att.dayoff_ot', 'Y' FROM DUAL             -- work on a day off / holiday is overtime
       UNION ALL SELECT 'att.round_minutes', '0' FROM DUAL
       UNION ALL SELECT 'att.weekend', '4,5' FROM DUAL             -- 0 Monday .. 6 Sunday (4,5 = Friday, Saturday; - = none)
       -- the HR system in this database (views HADER_V_EMPLOYEES / HADER_V_DEPARTMENTS / HADER_V_LEAVES)
       UNION ALL SELECT 'hr.import_employees', 'N' FROM DUAL
       UNION ALL SELECT 'hr.employees_minutes', '30' FROM DUAL
       UNION ALL SELECT 'hr.import_leaves', 'N' FROM DUAL
       UNION ALL SELECT 'hr.leaves_minutes', '30' FROM DUAL
       UNION ALL SELECT 'hr.leaves_days', '120' FROM DUAL
       UNION ALL SELECT 'hr.default_area', '' FROM DUAL            -- area code for people whose AREA_CODE is empty
       UNION ALL SELECT 'engine.today_minutes', '10' FROM DUAL
       UNION ALL SELECT 'ui.greetings', '' FROM DUAL               -- the greeting by time of day (JSON); empty = the program's
       -- the institution's HR system (hader/store.py hr.*): what its tables are called, how it writes its days and
       -- statuses, its rules; the university's by default; set by the system administrator
       UNION ALL SELECT 'hr.att_owner', '' FROM DUAL                                   -- the HR schema; empty = this one
       UNION ALL SELECT 'hr.table_types', 'HR_ATTENDANCE_TYPES' FROM DUAL
       UNION ALL SELECT 'hr.table_days', 'HR_ATTENDANCE_CONSTANT' FROM DUAL
       UNION ALL SELECT 'hr.table_groups', 'HR_ATTENDANCE_GROUPS' FROM DUAL
       UNION ALL SELECT 'hr.table_holidays', 'HR_VACATIONS' FROM DUAL
       UNION ALL SELECT 'hr.table_rotation', 'HR_ATTENDANCE_ROTATION_DAYS' FROM DUAL
       UNION ALL SELECT 'hr.table_hijri', 'HR_HIJRI_CALENDAR_DEVIATION' FROM DUAL
       UNION ALL SELECT 'hr.table_balance', 'HADER_V_LEAVE_BALANCE' FROM DUAL
       UNION ALL SELECT 'hr.holiday_status', 'A' FROM DUAL                             -- an approved official holiday
       UNION ALL SELECT 'hr.rotation_days', 'H=THU, S=SAT, M=MON, N=SUN' FROM DUAL     -- the rotation's letters as days
       UNION ALL SELECT 'hr.flex_minutes', '15' FROM DUAL                              -- a wider window to come in: flexible
       UNION ALL SELECT 'hr.day_hours', '7' FROM DUAL                                  -- a working day's hours
       UNION ALL SELECT 'hr.day_hours_rules', '' FROM DUAL                             -- dated hours by type / department
       UNION ALL SELECT 'hr.shift_prefix', 'HR' FROM DUAL                              -- the names of the shifts made
       UNION ALL SELECT 'hr.ramadan', '' FROM DUAL                                     -- Ramadan; empty = Hijri calendar
       UNION ALL SELECT 'hr.source_column', 'ATT_SOURCE' FROM DUAL                     -- the employees' source
       UNION ALL SELECT 'hr.sources', TO_CHAR('F=' || UNISTR('\0628\0635\0645\0629') || ', C=' || UNISTR('\0628\0637\0627\0642\0629')
         || ', P=' || UNISTR('\062D\0627\0633\0648\0628') || ', N=' || UNISTR('\0648\0631\0642\064A')) FROM DUAL
       UNION ALL SELECT 'hr.source_methods', 'F=finger+face+palm+password, C=card, P=manual, N=manual' FROM DUAL
       UNION ALL SELECT 'hr.verify_methods', '1=finger, 4=card, 15=face, 25=palm, 3=password, 0=password' FROM DUAL
       UNION ALL SELECT 'hr.col_late_times', 'MAX_LATE_MONTHLY' FROM DUAL               -- the types' limits
       UNION ALL SELECT 'hr.col_late_minutes', 'LATE_ALLOWED_MIN' FROM DUAL
       UNION ALL SELECT 'hr.col_ot_month', 'MAX_OVERTIME_HOURS' FROM DUAL
       UNION ALL SELECT 'hr.col_ot_week', 'OVERTIME_WEEK_HOURS' FROM DUAL
       UNION ALL SELECT 'hr.balance_rule', 'warn' FROM DUAL                            -- leave beyond the balance
       UNION ALL SELECT 'hr.table_leave_rules', 'HADER_V_LEAVE_RULES' FROM DUAL         -- the leave types' rules
       UNION ALL SELECT 'hr.late_ledger', 'off' FROM DUAL                               -- lateness from a leave
       UNION ALL SELECT 'hr.late_deduct', 'beyond' FROM DUAL
       UNION ALL SELECT 'hr.late_leave_code', '2' FROM DUAL
       UNION ALL SELECT 'hr.late_title', TO_CHAR(UNISTR('\0627\0639\062A\0645\0627\062F \062A\0623\062E\0631 \0639\0646 \0627\0644\062F\0648\0627\0645 \0634\0647\0631 ') || '{MM}-{YYYY}') FROM DUAL
       UNION ALL SELECT 'hr.ledger_proc', 'HADER_P_LEAVE_MOVE' FROM DUAL
       UNION ALL SELECT 'hr.late_ledger_done', '' FROM DUAL
       UNION ALL SELECT 'hr.ledger_entry_emp', '' FROM DUAL
       UNION ALL SELECT 'hr.deduct_pause', '' FROM DUAL
       UNION ALL SELECT 'hr.employees_where', 'EMP_TYPE IN (''E'', ''S'')' FROM DUAL         -- who is brought from HR                                 -- no deductions in these
       UNION ALL SELECT 'hr.table_relations', 'HADER_V_RELATIONS' FROM DUAL             -- relatives (bereavement)
       UNION ALL SELECT 'hr.relation_leaves', '20' FROM DUAL                            -- leave types by relative
       UNION ALL SELECT 'hr.leave_rule', 'warn' FROM DUAL                              -- a request out of them
       UNION ALL SELECT 'hr.source_flag', 'Y' FROM DUAL                                -- note a day by another way
       UNION ALL SELECT 'hr.sync', 'N' FROM DUAL                                       -- move them by itself, every:
       UNION ALL SELECT 'hr.sync_minutes', '1440' FROM DUAL                            -- (minutes) a day
       UNION ALL SELECT 'hr.sync_at', '' FROM DUAL
       UNION ALL SELECT 'hr.sync_last', '' FROM DUAL                                   -- when, and what it did
       -- the alerts (the same rules as the program's, hader/alerts.py): what reaches the bell of APEX app 141
       UNION ALL SELECT 'alerts.enabled', 'Y' FROM DUAL
       UNION ALL SELECT 'alerts.late.on', 'Y' FROM DUAL
       UNION ALL SELECT 'alerts.late.min_minutes', '1' FROM DUAL
       UNION ALL SELECT 'alerts.late.to_employee', 'Y' FROM DUAL
       UNION ALL SELECT 'alerts.late.to_managers', 'N' FROM DUAL
       UNION ALL SELECT 'alerts.absent.on', 'Y' FROM DUAL
       UNION ALL SELECT 'alerts.absent.at', '10:00' FROM DUAL
       UNION ALL SELECT 'alerts.absent.to_employee', 'Y' FROM DUAL
       UNION ALL SELECT 'alerts.absent.to_managers', 'Y' FROM DUAL
       UNION ALL SELECT 'alerts.missing_out.on', 'Y' FROM DUAL
       UNION ALL SELECT 'alerts.missing_out.at', '20:00' FROM DUAL
       UNION ALL SELECT 'alerts.missing_out.to_employee', 'Y' FROM DUAL
       UNION ALL SELECT 'alerts.missing_out.to_managers', 'N' FROM DUAL
       UNION ALL SELECT 'alerts.device_offline.on', 'Y' FROM DUAL
       UNION ALL SELECT 'alerts.device_offline.after_minutes', '10' FROM DUAL
       UNION ALL SELECT 'alerts.device_offline.to_managers', 'Y' FROM DUAL
       UNION ALL SELECT 'alerts.device_online.on', 'Y' FROM DUAL
       UNION ALL SELECT 'alerts.device_online.to_managers', 'Y' FROM DUAL
       UNION ALL SELECT 'alerts.request_new.on', 'Y' FROM DUAL
       UNION ALL SELECT 'alerts.request_new.to_managers', 'Y' FROM DUAL
       UNION ALL SELECT 'alerts.request_decided.on', 'Y' FROM DUAL
       UNION ALL SELECT 'alerts.request_decided.to_employee', 'Y' FROM DUAL
       UNION ALL SELECT 'alerts.daily_summary.on', 'N' FROM DUAL
       UNION ALL SELECT 'alerts.daily_summary.at', '09:30' FROM DUAL
       UNION ALL SELECT 'alerts.daily_summary.to_managers', 'Y' FROM DUAL
       -- the HR system's own punches table, written within the minute (as the Hader program's live send):
       -- columns ID, EMP_CODE, PUNCH_TIME, PUNCH_STATE, VERIFY_TYPE, TERMINAL_ID, TERMINAL_SN
       UNION ALL SELECT 'hr_table.enabled', 'N' FROM DUAL
       UNION ALL SELECT 'hr_table.name', 'ICLOCK_TRANSACTION' FROM DUAL
       UNION ALL SELECT 'hr_table.match', 'punch' FROM DUAL       -- punch: same person, time and terminal | id: ID + TERMINAL_ID
       UNION ALL SELECT 'hr_table.id_base', '-1' FROM DUAL        -- ID = base + PUNCH_ID (-1: chosen above the table's IDs)
       UNION ALL SELECT 'hr_table.last_id', '0' FROM DUAL         -- the last PUNCH_ID handed to the table
       UNION ALL SELECT 'hr_table.known_only', 'Y' FROM DUAL      -- only numbers in the HR employees table (others wait)
       UNION ALL SELECT 'hr_table.emp_table', 'HR_EMP_DATA' FROM DUAL
       UNION ALL SELECT 'hr_table.emp_col', '' FROM DUAL) s       -- its employee number column (empty: found)
ON (t.SKEY = s.k)
WHEN NOT MATCHED THEN INSERT (SKEY, SVALUE) VALUES (s.k, s.v);
UPDATE HDR_SETTINGS SET SVALUE = 'punch' WHERE SKEY = 'hr_table.match' AND SVALUE <> 'punch';
UPDATE HDR_SETTINGS SET SVALUE = 'F=finger+face+palm+password, C=card, P=manual, N=manual'
 WHERE SKEY = 'hr.source_methods' AND SVALUE = 'F=finger, C=card, P=manual, N=manual';
COMMIT;
DECLARE
  FUNCTION bytes_of (p_text IN CLOB) RETURN BLOB IS
    l_out   BLOB;
    l_clean CLOB := REGEXP_REPLACE(p_text, '[^A-Za-z0-9+/=]', '');
    l_pos   INTEGER := 1;
  BEGIN
    DBMS_LOB.CREATETEMPORARY(l_out, TRUE);
    WHILE l_pos <= NVL(DBMS_LOB.GETLENGTH(l_clean), 0) LOOP
      DBMS_LOB.APPEND(l_out, UTL_ENCODE.BASE64_DECODE(UTL_RAW.CAST_TO_RAW(DBMS_LOB.SUBSTR(l_clean, 16000, l_pos))));
      l_pos := l_pos + 16000;
    END LOOP;
    RETURN l_out;
  END;
BEGIN
  FOR r IN (SELECT p.ROWID RID, p.EMP_CODE, p.PHOTO FROM HADER_EMP_PHOTOS p
             WHERE p.SOURCE IS NULL AND p.PHOTO IS NOT NULL
               AND EXISTS (SELECT 1 FROM HDR_BIO_PHOTOS b WHERE b.EMP_CODE = p.EMP_CODE)) LOOP
    FOR b IN (SELECT CONTENT FROM HDR_BIO_PHOTOS WHERE EMP_CODE = r.EMP_CODE) LOOP
      IF DBMS_LOB.COMPARE(bytes_of(b.CONTENT), r.PHOTO) = 0 THEN
        UPDATE HADER_EMP_PHOTOS SET SOURCE = 'CAPTURE', UPDATED_AT = SYSDATE WHERE ROWID = r.RID;
        EXIT;
      END IF;
    END LOOP;
  END LOOP;
  COMMIT;
END;
/

-- ---------------------------------------------------------------- hdr_core.pks
CREATE OR REPLACE PACKAGE HDR_CORE AS
  -- Hader for Oracle APEX (native): settings, text helpers, the terminal command queue and the
  -- distribution of employees, templates and photos to the terminals of their areas.

  TYPE t_kv IS TABLE OF NVARCHAR2(4000) INDEX BY VARCHAR2(60);

  -- the Hader release these objects belong to: the APEX app warns when it is newer than them
  c_version CONSTANT VARCHAR2(20) := '2.3.5';

  -- TRUE while a terminal's upload is stored: the change triggers stay quiet (the upload distributes
  -- what it changes itself and marks its own days)
  g_quiet BOOLEAN := FALSE;

  -- settings ------------------------------------------------------------
  FUNCTION setting (p_key IN VARCHAR2, p_default IN VARCHAR2 DEFAULT NULL) RETURN VARCHAR2;
  PROCEDURE set_setting (p_key IN VARCHAR2, p_value IN VARCHAR2);
  FUNCTION on_ (p_key IN VARCHAR2) RETURN BOOLEAN;           -- a Y/N setting
  FUNCTION writing RETURN BOOLEAN;                           -- changes may be sent to the terminals
  FUNCTION server_tz (p_sn IN VARCHAR2 DEFAULT NULL) RETURN NUMBER;   -- hours, for the terminals
  -- the clock the terminals keep: the database's time in the zone set for the terminal (adms.timezone); the
  -- database's own clock when none is set
  FUNCTION local_now (p_sn IN VARCHAR2 DEFAULT NULL) RETURN DATE;

  -- text ------------------------------------------------------------------
  FUNCTION to_text (p_body IN BLOB) RETURN NCLOB;           -- UTF-8, older Arabic code page per line
  FUNCTION to_utf8 (p_text IN NCLOB) RETURN BLOB;
  FUNCTION kv (p_text IN NVARCHAR2, p_sep IN VARCHAR2 DEFAULT CHR(9)) RETURN t_kv;   -- keys lower-case
  FUNCTION kv_big (p_line IN NCLOB, p_key IN VARCHAR2, p_sep IN VARCHAR2 DEFAULT CHR(9)) RETURN CLOB;
  FUNCTION get (p_kv IN t_kv, p_key IN VARCHAR2, p_default IN NVARCHAR2 DEFAULT NULL) RETURN NVARCHAR2;
  FUNCTION num (p_value IN NVARCHAR2, p_default IN NUMBER DEFAULT 0) RETURN NUMBER;
  FUNCTION parse_time (p_text IN NVARCHAR2) RETURN DATE;
  FUNCTION valid_pin (p_pin IN VARCHAR2) RETURN BOOLEAN;
  FUNCTION field (p_text IN VARCHAR2, p_n IN PLS_INTEGER, p_sep IN VARCHAR2 DEFAULT CHR(9)) RETURN VARCHAR2;  -- n-th, empty ones count
  FUNCTION tsv_safe (p_value IN NVARCHAR2) RETURN NVARCHAR2;  -- no tab / newline inside a value
  FUNCTION dev_time (p_when IN DATE) RETURN NUMBER;           -- the terminals' compact clock value
  FUNCTION b64_blob (p_text IN CLOB) RETURN BLOB;             -- base64 text (line breaks and all) to its bytes

  -- the hours of an employee's working day on a date (hader/day_hours.py): of the rules hr.day_hours_rules that hold
  -- (hours|from|to|attendance type ids|department codes|name, ";" between), the one starting last; else the hours the
  -- employee's attendance type that day has most often; else hr.day_hours (7)
  FUNCTION day_hours (p_emp IN VARCHAR2, p_day IN DATE) RETURN NUMBER;

  -- terminal options (Key=Value lines kept in HDR_DEVICES.OPTIONS) ----------
  FUNCTION opt (p_sn IN VARCHAR2, p_key IN VARCHAR2) RETURN VARCHAR2;
  PROCEDURE apply_info (p_sn IN VARCHAR2, p_info IN t_kv);    -- merge INFO / options keys

  -- command queue -----------------------------------------------------------
  FUNCTION is_change (p_content IN NVARCHAR2) RETURN BOOLEAN;   -- anything but INFO / DATA QUERY
  FUNCTION queue (p_sn IN VARCHAR2, p_content IN NCLOB, p_title IN NVARCHAR2 DEFAULT NULL) RETURN NUMBER;
  PROCEDURE queue (p_sn IN VARCHAR2, p_content IN NCLOB, p_title IN NVARCHAR2 DEFAULT NULL);
  PROCEDURE requeue_stale (p_minutes IN NUMBER DEFAULT 15, p_max_attempts IN NUMBER DEFAULT 3);

  -- command texts -------------------------------------------------------------
  -- as much of a name as a terminal's name field holds (24 bytes: about 12 Arabic letters), never half a letter
  FUNCTION terminal_name (p_name IN NVARCHAR2, p_bytes IN NUMBER DEFAULT 24) RETURN NVARCHAR2;
  FUNCTION whole_words (p_held IN NVARCHAR2, p_full IN NVARCHAR2) RETURN BOOLEAN;
  FUNCTION name_bytes (p_sn IN VARCHAR2) RETURN NUMBER;
  FUNCTION cmd_user (p_emp_code IN VARCHAR2, p_sn IN VARCHAR2 DEFAULT NULL) RETURN NCLOB;
  FUNCTION cmd_user_delete (p_emp_code IN VARCHAR2) RETURN NCLOB;
  FUNCTION cmd_query (p_table IN VARCHAR2, p_pin IN VARCHAR2 DEFAULT NULL) RETURN NCLOB;
  FUNCTION cmd_query_attlog (p_from IN DATE, p_to IN DATE) RETURN NCLOB;

  -- employees on terminals ------------------------------------------------------
  FUNCTION uses_biodata (p_sn IN VARCHAR2) RETURN BOOLEAN;
  FUNCTION push_employee (p_sn IN VARCHAR2, p_emp_code IN VARCHAR2, p_with_bio IN BOOLEAN DEFAULT TRUE) RETURN NUMBER;
  FUNCTION sync_device (p_sn IN VARCHAR2) RETURN NUMBER;     -- every employee of its area (checks capacity)
  FUNCTION employee_changed (p_emp_code IN VARCHAR2, p_old_areas IN VARCHAR2 DEFAULT NULL,
                             p_with_bio IN BOOLEAN DEFAULT FALSE) RETURN NUMBER;   -- p_old_areas: 'id,id'
  FUNCTION employee_removed (p_emp_code IN VARCHAR2, p_areas IN VARCHAR2) RETURN NUMBER;
  -- people, every kind of template and the photos a terminal holds; p_again 'Y' (asked by a person): table
  -- queries tried once more even if the terminal refused them before
  FUNCTION pull_bio (p_sn IN VARCHAR2, p_pin IN VARCHAR2 DEFAULT NULL, p_again IN VARCHAR2 DEFAULT 'N') RETURN NUMBER;
  -- the terminal sends everything it holds again by itself: its marks cleared, its options read again
  FUNCTION resend_everything (p_sn IN VARCHAR2) RETURN NUMBER;
  -- it refused a table query (-1004): remembered, the other queries waiting closed, everything asked the other way
  PROCEDURE no_table_queries (p_sn IN VARCHAR2);
  FUNCTION bio_delete (p_emp_code IN VARCHAR2, p_kinds IN VARCHAR2, p_fingers IN VARCHAR2 DEFAULT NULL,
                       p_terminals IN BOOLEAN DEFAULT TRUE) RETURN NUMBER;
  PROCEDURE distribute_user (p_emp_code IN VARCHAR2, p_source_sn IN VARCHAR2);
  PROCEDURE distribute_template (p_bio_id IN NUMBER, p_source_sn IN VARCHAR2);
  -- The card picture (HADER_EMP_PHOTOS with SOURCE HAND, DEVICE or NULL) is what a terminal shows when the
  -- employee punches. The recognition photo (HDR_BIO_PHOTOS; SOURCE CAPTURE where it stands in on the pages)
  -- is what it learns the face from, and is never sent as the card picture.
  PROCEDURE distribute_userpic (p_emp_code IN VARCHAR2, p_source_sn IN VARCHAR2);
  PROCEDURE withdraw_userpic (p_emp_code IN VARCHAR2, p_source_sn IN VARCHAR2);   -- the terminals drop theirs
  PROCEDURE userpic_back (p_emp_code IN VARCHAR2, p_sn IN VARCHAR2);   -- the chosen one again (not in a loop)
  -- a terminal holding the person without the name kept here (enrolled there by number only) or with another
  -- one is sent it (not in a loop); p_held: the name it holds
  PROCEDURE name_back (p_emp_code IN VARCHAR2, p_sn IN VARCHAR2, p_held IN NVARCHAR2);
  FUNCTION is_recognition_photo (p_emp_code IN VARCHAR2, p_pic IN BLOB) RETURN BOOLEAN;
  PROCEDURE distribute_photo (p_emp_code IN VARCHAR2, p_bio_type IN NUMBER, p_source_sn IN VARCHAR2);
  -- the recognition photo to every terminal of the employee's areas (they learn the face from it); how many
  FUNCTION send_photo (p_emp_code IN VARCHAR2, p_bio_type IN NUMBER DEFAULT 9) RETURN NUMBER;
  PROCEDURE mark_dirty (p_emp_code IN VARCHAR2, p_day IN DATE);
  PROCEDURE mark_days (p_emp_code IN VARCHAR2, p_from IN DATE, p_to IN DATE);   -- past and today only
  PROCEDURE mark_pending (p_kind IN VARCHAR2, p_key IN VARCHAR2, p_added IN VARCHAR2 DEFAULT NULL,
                          p_removed IN VARCHAR2 DEFAULT NULL, p_deleted IN BOOLEAN DEFAULT FALSE,
                          p_from IN DATE DEFAULT NULL);

  -- terminal settings sent as commands ---------------------------------------------
  PROCEDURE set_server (p_sn IN VARCHAR2, p_host IN VARCHAR2, p_port IN NUMBER, p_reboot IN BOOLEAN DEFAULT TRUE);
  PROCEDURE set_clock (p_sn IN VARCHAR2, p_when IN DATE DEFAULT NULL);
  PROCEDURE simple (p_sn IN VARCHAR2, p_action IN VARCHAR2);  -- info, check, reboot, clear_log, clear_photo, clear_data
  PROCEDURE set_option (p_sn IN VARCHAR2, p_key IN VARCHAR2, p_value IN NVARCHAR2);
  PROCEDURE enroll (p_sn IN VARCHAR2, p_emp_code IN VARCHAR2, p_bio_type IN NUMBER, p_finger IN NUMBER DEFAULT 0);

  -- errors raised to APEX pages
  e_read_only EXCEPTION;
  PRAGMA EXCEPTION_INIT (e_read_only, -20601);
  e_capacity EXCEPTION;
  PRAGMA EXCEPTION_INIT (e_capacity, -20602);
END HDR_CORE;
/

