-- ---------------------------------------------------------------- hdr_engine.pks
CREATE OR REPLACE PACKAGE HDR_ENGINE AS
  -- Attendance calculation (the same rules as Hader): for every employee and day it resolves the
  -- timetables (one-day override > personal schedule > department schedule > none), matches punches
  -- to the check-in / check-out windows and works out late, early leave, absence, worked time,
  -- overtime, leave and holidays. Results go to HADER_ATT_DAILY.

  -- calculate a period (all employees, or one) and store it
  PROCEDURE calc (p_from IN DATE, p_to IN DATE, p_emp_code IN VARCHAR2 DEFAULT NULL);
  -- what changed since the last time (new punches, leave, schedules): HDR_DIRTY
  PROCEDURE calc_dirty;
  -- employee-days to calculate again (a day's change can move the neighbouring night shift)
  PROCEDURE touch_period (p_emp_code IN VARCHAR2, p_from IN DATE, p_to IN DATE);
  PROCEDURE touch_all (p_from IN DATE, p_to IN DATE);

  -- one day as text "status|worked|late|..." (tests and the day details of the plug-ins)
  FUNCTION explain (p_emp_code IN VARCHAR2, p_day IN DATE) RETURN VARCHAR2;
  -- a day's punches as the program's reports write them: each one of the next morning marked (+1)
  FUNCTION punch_list (p_punches IN VARCHAR2, p_first IN DATE, p_day IN DATE) RETURN VARCHAR2 DETERMINISTIC;
END HDR_ENGINE;
/

