-- ---------------------------------------------------------------- hdr_jobs.pks
CREATE OR REPLACE PACKAGE HDR_JOBS AS
  -- The background work of Hader for Oracle APEX, run every minute by the scheduler job HDR_TICK
  -- (hdr_scheduler.sql): changes to the terminals, attendance calculation, the alerts, the HR import and
  -- the requests of the "Hader sync" button.

  PROCEDURE tick;

  -- employees, departments and leave from the HR views (HADER_V_EMPLOYEES / _DEPARTMENTS / _LEAVES)
  FUNCTION import_employees RETURN VARCHAR2;
  FUNCTION import_leaves RETURN VARCHAR2;

  -- changed people / terminals / company rules noted by the triggers
  PROCEDURE apply_pending;

  -- one request of HADER_REQUESTS (the button runs it at once; the job runs those inserted otherwise)
  PROCEDURE run_request (p_id IN RAW);
  PROCEDURE run_requests;
  -- run it now in the background (a one-off scheduler job), so the page does not wait; the
  -- every-minute job takes it anyway if this cannot start
  PROCEDURE start_request (p_id IN RAW);

  -- Hader for Oracle APEX takes over (native.active = Y): installed over a schema the Hader program wrote to,
  -- it stands still until this. The same punch found twice in HADER_PUNCHES is moved to HDR_PUNCHES_DUPLICATES
  -- (kept, not lost) and the punch index made; HDR_SEQ moves past the punch numbers already there.
  FUNCTION activate RETURN VARCHAR2;
  FUNCTION active RETURN BOOLEAN;

  -- the punches not handed yet to the HR system's own punches table (hr_table.*), as the Hader program's
  -- live send did: ID = base + PUNCH_ID, numbers unknown to HR wait, a refused row never holds up the others
  FUNCTION hr_table_push RETURN VARCHAR2;

  -- the same work as a request, for APEX processes: SYNC / PUNCHES / EMPLOYEES / LEAVES / RECALC
  FUNCTION do_request (p_kind IN VARCHAR2, p_emp_code IN VARCHAR2 DEFAULT NULL, p_from IN DATE DEFAULT NULL,
                       p_to IN DATE DEFAULT NULL) RETURN VARCHAR2;
END HDR_JOBS;
/

